local function ReplaceTableRowValue(row, fieldName, newResourceName)
    local HeaderInfos = row.HeaderInfos
    local info = try_get_value(HeaderInfos, fieldName)
    local info2 = try_get_value(HeaderInfos, newResourceName)
    if isNotNull(info2) then
        local replacekey =  parse_string(row, newResourceName)
        if replacekey and string.len(replacekey)  > 0  then
            row[info.ColumnIndex] = parse_string(row, newResourceName)    
        end
    end
end
