---@param row TableML.TableFileRow
function CardSkinVo:FillVo(row)
    base.FillVo(self,row)
    
    self.skinId = parse_number(row, "skinId")
    self.isNormal = parse_number(row, "isHarmonious") == 0
    self.roleId = parse_number(row, "roleId")
    self.name = ParseUtils.ParseLocalizeText(row, "name")
    self.desc = ParseUtils.ParseLocalizeText(row, "desc")
    self.desc2 = ParseUtils.ParseLocalizeText(row, "desc2")
    self.mode = parse_string(row, "mode")
    ---保存一份和谐的
    local lobbyModeNormal = parse_string(row, "lobbyMode")
    self.lobbyModeHarmonious = GetHarmoniousName(lobbyModeNormal, CardLobbyPath)
    ---通过 IsThisSkinInHeXieMode 检查是否和谐过的
    self.lobbyMode = HarmoniousName(row, "lobbyMode", self.skinId, CardLobbyPath)
    self.skinScene = parse_string(row, "skinScene", "")
    self._scenePosition = parse_string(row, "scenePosition", "")
    self._sceneRotation = parse_string(row, "sceneRotation", "")
    self.unlockType = parse_number(row, "unlockType")
    self.effectMode = parse_string(row, "effectMode")
    self.dialogueTag = parse_number(row, "dialogueTag")
    self.goodOpinionTag = parse_number(row, "goodOpinionTag")
    self.effectTag = parse_number(row, "effectTag")
    self.cardHeadList = HarmoniousPath(row, "cardHeadList", self.skinId )
    local heXieTables  = {
        "bigCardDrawing",
        "cardDrawing",
        "hdCardDrawing"
    }
    for i =1 , #heXieTables do
        if IS_HARMONIOUS then
            ReplaceTableRowValue(row , heXieTables[i] , heXieTables[i] .. "_hexie")
        end
        self[heXieTables[i]] = parse_pathNameByData(parse_string(row, heXieTables[i])) 
    end
    self.buffHead = ParseUtils.ParsePathName(row, "buffHead")
    self.Background = ParseUtils.ParsePathName(row, "Background")
    self.spSkillName = ParseUtils.ParseLocalizeText(row, "spSkillName")
    self.enterFX = parse_number(row, "fxBattleEnter")
    local enterTimeline = parse_string(row, "enterTimeline")
    if string.isEmpty(enterTimeline) or enterTimeline == '0' then
        self.enterTimeLine = nil
    else
        self.enterTimeLine = enterTimeline
    end
    local endTimeline = parse_string(row, "endTimeline")
    if string.isEmpty(endTimeline) or endTimeline == '0' then
        self.endTimeline = nil
    else
        self.endTimeline = endTimeline
    end
    local endTimeline50 = parse_string(row, "endTimeline50")
    if string.isEmpty(endTimeline50) or endTimeline50 == '0' then
        self.endTimeline50 = nil
    else
        self.endTimeline50 = endTimeline50
    end
    self.status = parse_number(row, "status")
    local enterSound = parse_string(row, "enterSound")
    self.enterSound = (not (string.isEmpty(enterSound) or enterSound == '0')) and enterSound or nil         --- 入场音频
    self.battleBossHead = ParseUtils.ParsePathName(row, "battleBossHead")
    
    local cardAttributes = CardAttributes.New()
    self.attributes = cardAttributes:FillVo(row)
    self.tag = parse_number(row, "tag")
    self.catPrefab = parse_string(row, "catPrefab")
    self.isHandbook = parse_number(row, "inHandBook", 0) == 1

    self.skinMaxLevel =  parse_number(row, "skinMaxLevel", 0)
    self.version = parse_pathName(row, "version")
    self.jump =  parse_number(row, "jump", 0)
    
    self.endCtrl = parse_number(row, "endCtrl", 0)
    local uiCover = parse_number(row, "uiCover", 1)
    if uiCover == 0 then
        uiCover = 1
    end
    self.uiCover = uiCover
    self.color = parse_string(row, "color", 'FFFFFF')
    self.intensity = parse_number(row, "intensity", 0.9)
    self._lightDirection = parse_string(row, "lightDirection", "")
    self.isMonster = parse_number(row, "isMonster", 0)
end

