function CardSkinVo:GetSkinScenePosition()
    if string.isEmpty(self._scenePosition) then
        return
    end
    if self.scenePosition == nil then
        self.scenePosition = Vector3.New(SafeUnpack(Tools.splitToNum(self._scenePosition, ';')))
    end
    return self.scenePosition
end

function CardSkinVo:GetSceneRotation()
    if string.isEmpty(self._sceneRotation) then
        return
    end
    if self.sceneRotation == nil then
        local sceneRotationVector3 = Vector3.New(SafeUnpack(Tools.splitToNum(self._sceneRotation, ';')))
        self.sceneRotation = Quaternion.Euler(sceneRotationVector3.x, sceneRotationVector3.y, sceneRotationVector3.z)
    end
    return self.sceneRotation
end

function CardSkinVo:GetLightDirection()
    if string.isEmpty(self._lightDirection) then
        return
    end
    if self.lightDirection == nil then
        self.lightDirection = Vector3.New(SafeUnpack(Tools.splitToNum(self._lightDirection, ';')))
    end
    return self.lightDirection
end

function CardSkinVo:GetRare()
    local rareRef = {
        [1] = 1,
        [2] = 1,
        [3] = 2,
        [4] = 3,
        [5] = 4,
    }
    
    return rareRef[checkInt(self.tag)] or 1
end

function CardSkinVo:CheckAndGetLobbyMode()
    return self.isNormal and self.lobbyMode or self.lobbyModeHarmonious
end

return CardSkinVo
